// Legacy GEO interface of mrdoob/slop-newyork (the engine's geodata module), now backed by the Utrecht inner city.
// Everything Manhattan-specific is empty; the mapped OSM city lives in GEO.utrecht (the irregular-city data path
// of the engine, see utrecht-geometry.js) and is generated by tools/build-utrecht-geodata.mjs.
import { UTRECHT_DATA } from './utrecht-geodata.js';

const [minX, minZ, maxX, maxZ] = UTRECHT_DATA.meta.bounds;

export const GEO = {
  version: 2,
  city: 'Utrecht',
  cityName: 'Utrecht',
  frame: { bearingDeg: 0, origin: 'Domtoren', units: 'm', cutZ: minZ, strip: 20, sidewalk: 3 },
  manhattan: [minX, minZ, maxX, minZ, maxX, maxZ, minX, maxZ],
  upperManhattan: [],
  streets: [],
  avenues: [],
  broadway: [],
  piers: [],
  islands: {},
  boroughs: { newJersey: [], brooklyn: [], queens: [], bronx: [], statenIsland: [] },
  bridges: {},
  points: {},
  plazas: [],
  centralPark: { bounds: { minX, maxX, minZ, maxZ }, lawns: [], water: UTRECHT_DATA.water, drives: [] },
  parks: UTRECHT_DATA.parks.map((p) => ({ name: p.name, kind: p.kind, rings: [p.ring], holes: p.holes })),
  landmarks: UTRECHT_DATA.landmarks,
  roads: [],
  blocks: [],
  roadGraph: UTRECHT_DATA.roadGraph,
  utrecht: UTRECHT_DATA
};
